        public static int Sides(int panel)=>16;
        public static float Top(int panel)=>Rows[panel][0].y;
        public static float Bottom(int panel)=>Rows[panel][Rows[panel].Length-1].y;
        static float Slope(float a,float b,float ha,float hb) {
            if(a*b<=0)return 0;float wa=2*hb+ha,wb=hb+2*ha;return (wa+wb)/(wa/a+wb/b);
        }
        static float Cubic(float a,float b,float ma,float mb,float h,float t) {
            float t2=t*t,t3=t2*t;return (2*t3-3*t2+1)*a+(t3-2*t2+t)*h*ma+(-2*t3+3*t2)*b+(t3-t2)*h*mb;
        }
        public static float[] Stations(int panel) {
            var p=Rows[panel];var ys=new System.Collections.Generic.List<float>{Top(panel),.90f,.82f,.74f,.66f};
            for(int row=1;row<p.Length/16;row++)if(p[row*16].y<.66f)ys.Add(p[row*16].y);
            ys.Sort((a,b)=>b.CompareTo(a));return ys.ToArray();
        }
        static Vector3 Column(int panel,float y,int col) {
            var p=Rows[panel];int stride=Sides(panel),count=p.Length/stride,row=0;while(row<count-2&&p[(row+1)*stride].y>y)row++;
            float h=p[row*stride].y-p[(row+1)*stride].y,t=Mathf.Clamp01((p[row*stride].y-y)/h);
            Vector3 a=p[row*stride+col],b=p[(row+1)*stride+col],result=a;
            for(int k=0;k<3;k++) {
                if(k==1){result.y=y;continue;}
                float d=(b[k]-a[k])/h,ma=d,mb=d;
                if(row>0){float hp=p[(row-1)*stride].y-p[row*stride].y;ma=Slope((a[k]-p[(row-1)*stride+col][k])/hp,d,hp,h);}
                if(row<count-2){float hn=p[(row+1)*stride].y-p[(row+2)*stride].y;mb=Slope(d,(p[(row+2)*stride+col][k]-b[k])/hn,h,hn);}
                result[k]=Cubic(a[k],b[k],ma,mb,h,t);
            }
            return result;
        }
        public static Vector3 Surface(int panel,float y,float around) {
            int sides=Sides(panel);float f=Mathf.Repeat(around,1)*sides;int j=(int)f;float t=f-j;
            Vector3 a=Column(panel,y,j),b=Column(panel,y,(j+1)%sides),before=Column(panel,y,(j+sides-1)%sides),after=Column(panel,y,(j+2)%sides),p=a;
            for(int k=0;k<3;k++) {
                if(k==1){p.y=y;continue;}
                float d=b[k]-a[k];p[k]=Cubic(a[k],b[k],Slope(a[k]-before[k],d,1,1),Slope(d,after[k]-b[k],1,1),1,t);
            }
            return p;
        }
